(7029262, 1066414, 159525, '<td valign="top">I love the smile on her face!  What a wonderful warm feeling this photo has.</td>', 'I love the smile on her face!  What a wonderful warm feeling this photo has.', '2013-04-29 20:24:45.000000', NULL, 1),
