(7029996, 1065532, 93283, '<td valign="top">Interesting background, nice well lit foreground, could have used a little color boost and a little more sharpening in the foreground. Just my two cents :)  a 6 from me</td>', 'Interesting background, nice well lit foreground, could have used a little color boost and a little more sharpening in the foreground. Just my two cents :)  a 6 from me', '2013-04-30 21:48:58.000000', NULL, 1),
