(7030002, 1065574, 93283, '<td valign="top">Hmmm... A Black and White image in a colorful challenge...Daring... and bonus points from me. I wish I could tell you why I really like this image, but I can''t. I guess it kinda reminds me of the swamp and Clyde Butcher  :) 8</td>', 'Hmmm... A Black and White image in a colorful challenge...Daring... and bonus points from me. I wish I could tell you why I really like this image, but I can''t. I guess it kinda reminds me of the swamp and Clyde Butcher  :) 8', '2013-04-30 21:59:20.000000', NULL, 1),
(7030003, 1066291, 93283, '<td valign="top">Snow in a Spring challenge... Booyah!!! Love it!!! Interesting composition and nice detail 8</td>', 'Snow in a Spring challenge... Booyah!!! Love it!!! Interesting composition and nice detail 8', '2013-04-30 22:00:23.000000', NULL, 1),
(7030004, 1066411, 93283, '<td valign="top">Love the background on this image! Really makes the shot. 8</td>', 'Love the background on this image! Really makes the shot. 8', '2013-04-30 22:01:10.000000', NULL, 1),
(7030005, 1066632, 93283, '<td valign="top">Stunning image, nice capture, and wonderful detail. I personally would have brought the crop in a little tighter to have less of the horse''s neck in the frame. Either way, wonderful shot 8</td>', 'Stunning image, nice capture, and wonderful detail. I personally would have brought the crop in a little tighter to have less of the horse''s neck in the frame. Either way, wonderful shot 8', '2013-04-30 22:02:40.000000', NULL, 1),
(7030035, 1066351, 136989, '<td valign="top">Beautiful pastels. Love the bokeh.</td>', 'Beautiful pastels. Love the bokeh.', '2013-04-30 22:38:38.000000', NULL, 1),
(7030037, 1066541, 136989, '<td valign="top">You made me think of all sorts of hiking trips in my past where I pondered why so many switch backs.  What a beautiful bridge for a trail.  I love the greens and wish I could visit.</td>', 'You made me think of all sorts of hiking trips in my past where I pondered why so many switch backs.  What a beautiful bridge for a trail.  I love the greens and wish I could visit.', '2013-04-30 22:40:46.000000', NULL, 1),
(7030038, 1065610, 136989, '<td valign="top">A bright blotch of color on an otherwise nondescript heap.  Pretty. Liking the posies.</td>', 'A bright blotch of color on an otherwise nondescript heap.  Pretty. Liking the posies.', '2013-04-30 22:41:51.000000', NULL, 1),
(7030040, 1066632, 136989, '<td valign="top">I really like the contrast of white and green.  You did an amazing job on the horse.  He''s both in detail and soft and dreamy.  Gorgeous.  Oh and the dainty little yellow flowers are just bonus.</td>', 'I really like the contrast of white and green.  You did an amazing job on the horse.  He''s both in detail and soft and dreamy.  Gorgeous.  Oh and the dainty little yellow flowers are just bonus.', '2013-04-30 22:43:32.000000', NULL, 1),
(7030041, 1065716, 136989, '<td valign="top">Nice find.  I think it''s safe to say that the greenery is structural at this point.  Solid comp, love the greens and grays.</td>', 'Nice find.  I think it''s safe to say that the greenery is structural at this point.  Solid comp, love the greens and grays.', '2013-04-30 22:45:54.000000', NULL, 1),
(7030042, 1065651, 136989, '<td valign="top">I like the comp. great leading lines.  Not sure how it will do in a spring challenge though.</td>', 'I like the comp. great leading lines.  Not sure how it will do in a spring challenge though.', '2013-04-30 22:47:30.000000', NULL, 1),
(7030045, 1065525, 136989, '<td valign="top">So cute and fuzzy.  Great details. The lighting seems a but dark but as moving the subjects isn''t viable it certainly works.</td>', 'So cute and fuzzy.  Great details. The lighting seems a but dark but as moving the subjects isn''t viable it certainly works.', '2013-04-30 22:49:17.000000', NULL, 1),
(7030047, 1066226, 136989, '<td valign="top">Beautiful birds!  The lines in the water create highlights that are a bit distracting. Especially as they really mess with your reflections.</td>', 'Beautiful birds!  The lines in the water create highlights that are a bit distracting. Especially as they really mess with your reflections.', '2013-04-30 22:50:27.000000', NULL, 1),
(7030049, 1066624, 136989, '<td valign="top">Beautiful colors and nice composition.  Focus is a bit off at least to me.</td>', 'Beautiful colors and nice composition.  Focus is a bit off at least to me.', '2013-04-30 22:51:39.000000', NULL, 1),
(7030050, 1066676, 93283, '<td valign="top">Love this!!! Daring in a colorful Spring challenge... Nice tones and detail, also tells a story... a perfect 10 from me!</td>', 'Love this!!! Daring in a colorful Spring challenge... Nice tones and detail, also tells a story... a perfect 10 from me!', '2013-04-30 22:54:17.000000', NULL, 1),
(7030051, 1065286, 136989, '<td valign="top">Borders on abstract. I like that.  Nice subject but maybe a bit dark on the lighting.</td>', 'Borders on abstract. I like that.  Nice subject but maybe a bit dark on the lighting.', '2013-04-30 22:55:11.000000', NULL, 1),
(7030052, 1066655, 93283, '<td valign="top">Nice background and good DoF. Colors and tones work well too. These shots are tough and you did well. A 7 from me. A little burn on the Ladybug wing could have helped the light reflection. Overall a great shot!</td>', 'Nice background and good DoF. Colors and tones work well too. These shots are tough and you did well. A 7 from me. A little burn on the Ladybug wing could have helped the light reflection. Overall a great shot!', '2013-04-30 22:56:13.000000', NULL, 1),
(7030053, 1066674, 136989, '<td valign="top">Terrific idea for the grain challenge too.  I like the colors but the white bulb is a bit distracting for me.</td>', 'Terrific idea for the grain challenge too.  I like the colors but the white bulb is a bit distracting for me.', '2013-04-30 22:56:39.000000', NULL, 1),
