(7030183, 1066226, 68504, '<td valign="top">what a treat.</td>', 'what a treat.', '2013-05-01 01:30:10.000000', NULL, 0),
(7030184, 1066011, 54446, '<td valign="top">I gave this a "7".  It''s okay, but lacks elements of interest.  The sky is especially bland and featureless.  Your image would have benefitted from an image size allowance greater than 800 pixels.  Otherwise, you are too wide angle ... distant.  You need to choose a closer foreground subject of interest and allow the image to assume a 3 dimensional look.</td>', 'I gave this a "7".  It''s okay, but lacks elements of interest.  The sky is especially bland and featureless.  Your image would have benefitted from an image size allowance greater than 800 pixels.  Otherwise, you are too wide angle ... distant.  You need to choose a closer foreground subject of interest and allow the image to assume a 3 dimensional look.', '2013-05-01 01:32:59.000000', NULL, 0),
