(7034977, 1066134, 117474, '<td valign="top">Got the asigmatic for this''un!<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1000203" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1000203.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1000203.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1000203.gif"/></a></td>', 'Got the asigmatic for this''un!', '2013-05-09 14:40:18.000000', NULL, 0),
(7035738, 1066521, 159200, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Sirashley:</b></div><hr/><i> Rose is nice and sharp. The lighting is even and not too harsh but the background is a bit busy. 6 </i></td></tr></table> <br/> <br/>Thanks for the feedback! Glad you liked it! This picture was taken at a restaurant in the middle of a city, hence the ''busy'' feel. But everything is taken on board! Thanks.</td>', 'Originally posted by Sirashley: Rose is nice and sharp. The lighting is even and not too harsh but the background is a bit busy. 6   Thanks for the feedback! Glad you liked it! This picture was taken at a restaurant in the middle of a city, hence the ''busy'' feel. But everything is taken on board! Thanks.', '2013-05-11 08:51:08.000000', NULL, 0),
(7042883, 1066374, 161988, '<td valign="top">This photo has added a new and exciting perspective and angle for me to take flower shots in the future.  Admittedly I haven''t taken many flower pictures.  However, your camera angle, use of a wide lens, with the beautiful sky for a backdrop is absolutely gorgeous.  I can''t wait to attempt this myself.  Remember "imitation is the sincerest form of flattery".</td>', 'This photo has added a new and exciting perspective and angle for me to take flower shots in the future.  Admittedly I haven''t taken many flower pictures.  However, your camera angle, use of a wide lens, with the beautiful sky for a backdrop is absolutely gorgeous.  I can''t wait to attempt this myself.  Remember "imitation is the sincerest form of flattery".', '2013-05-24 22:44:56.000000', NULL, 0),
(7042990, 1066374, 114285, '<td valign="top">I wasn''t around for this challenge, but I did however see this when it ended, I loved it so much, you did a wonderful job with that low angle and the long shutter speed, it''s so alive, well done.</td>', 'I wasn''t around for this challenge, but I did however see this when it ended, I loved it so much, you did a wonderful job with that low angle and the long shutter speed, it''s so alive, well done.', '2013-05-25 09:42:26.000000', NULL, 0),
(7043210, 1066683, 92577, '<td valign="top">Great observation and title. But as things are, quick voters will just see a view of a park.<br/>I''d have cropped all the background to leave only the couple by the water''s edge. Then added a touch of (romantic) glow.<br/>Just my thoughts...</td>', 'Great observation and title. But as things are, quick voters will just see a view of a park.I''d have cropped all the background to leave only the couple by the water''s edge. Then added a touch of (romantic) glow.Just my thoughts...', '2013-05-26 07:16:41.000000', NULL, 0),
(7045478, 1066581, 162721, '<td valign="top">great pic! the blurred background surely does the trick !<br/></td>', 'great pic! the blurred background surely does the trick !', '2013-05-31 03:52:51.000000', NULL, 0);
